<?php require 'config.php'; if (is_admin()) { header('Location: dashboard.php'); exit; } $error=''; if ($_SERVER['REQUEST_METHOD']==='POST') { $username=$_POST['username']??''; $password=$_POST['password']??''; $stmt=$conn->prepare('SELECT id, username FROM admins WHERE username=? AND password=?'); $stmt->bind_param('ss',$username,$password); $stmt->execute(); $admin=$stmt->get_result()->fetch_assoc(); if($admin){$_SESSION['admin_id']=$admin['id'];$_SESSION['admin_name']=$admin['username'];header('Location: dashboard.php');exit;} $error='Invalid username or password.'; } $page_title='Admin Login'; require 'header.php'; ?>
<div class="auth-wrap"><form class="panel auth" method="post"><p class="eyebrow">Administrator Area</p><h1>Welcome back</h1><?php if($error): ?><p class="alert error"><?=e($error)?></p><?php endif; ?><label>Username</label><input name="username" required><label>Password</label><input type="password" name="password" required><button>Sign In</button><small>Demo: admin / admin123</small></form></div>
